        const { input, output } = data;
        let error = 0;
        for (let i = 0; i < input.length; i++) {
            let value = input[i];
            for (let j = 0; j < output.length; j++) {
                let delta = output[j] - value;
                error += delta ** 2;
                for (let k = 0; k < network.weights.length; k++) {
                    for (let l = 0; l < network.weights[k].length; l++) {
                        let weight = network.weights[k][l];
