import re
import urllib.parse

def get_user_input():
    user_input = ""
    while True:
        user_input = input("Please type your message here.\n> ")
        if re.match(r"^[a-zA-Z0-9_\-+]+[\s\S]*{", user_input):
            break
        else:
            print("Invalid input. Please try again.")

    parsed_input = urllib.parse.quote(user_input)

    return parsed_input

