import requests
from BeautifulSoup import BeautifulSoup

url = "https://www.wired.com/2015/12/30/join-the-snake-game/"

def scrape_snake_game():
    page = requests.get(url, verify = False)
    soup = BeautifulSoup(page.text, "html.parser")
    table = soup.find('table', {'class': 'snake-game'})

    if table:
        total_score = 0
        for row in table.find_all('tr'):
            cells = row.find_all('td')
            for cell in cells:
                text = cell.get_text()
                if text.isdigit():
                    total_score += int(text)

        return total_score
    else:
        return 0

print(scrape_snake_game())

